export default function Collection() {
  const location = useLocation();
  const isTrans = location.pathname.includes("trans");

  const [collections, setCollections] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");

  // ✅ 서버에서 찜 목록 불러오기
  useEffect(() => {
    const fetchRecipes = async () => {
      try {
        const category = isTrans ? "trans" : "recipe"; // 분기
        const res = await axios.post(
          "/api/my/recipe",
          { category },
          { withCredentials: true }
        );
        setCollections(res.data || []);
      } catch (e) {
        console.error("목록 불러오기 실패:", e);
        setErr("목록을 불러올 수 없습니다.");
      } finally {
        setLoading(false);
      }
    };
    fetchRecipes();
  }, [isTrans]);

  // ✅ 찜 토글 → 서버에도 반영
  const handleToggleLike = async (rcpId) => {
    try {
      const res = await axios.post(
        "/api/recipe/like",
        { rcp_Id: rcpId }, // 백엔드 DTO에 맞게 전송
        { withCredentials: true }
      );

      const { liked, likeCount } = res.data;

      setCollections((prev) =>
        prev.map((item) =>
          item.rcpId === rcpId ? { ...item, liked, likeCount } : item
        )
      );
    } catch (e) {
      console.error("찜 토글 실패:", e);
      alert("찜 처리 실패");
    }
  };

  // 변환 레시피: 삭제
  const handleDeleteTrans = async (rcpId) => {
    try {
      await axios.post(
        "/api/recipe/delete",
        { rcp_Id: rcpId },
        { withCredentials: true }
      );
      setCollections((prev) => prev.filter((item) => item.rcpId !== rcpId));
    } catch (e) {
      console.error("변환 레시피 삭제 실패:", e);
      alert("삭제 실패");
    }
  };

  const handleClearAll = () => {
    setCollections([]);
  };

  return (
    <div className="app-wrap">
      <div className="app">
        <Header title="나의 레시피" />
        <CollectionTabs />

        <div className="content-scroll">
          {loading ? (
            <p
              style={{
                textAlign: "center",
                marginTop: "20px",
                fontSize: "13px",
              }}
            >
              불러오는 중...
            </p>
          ) : err ? (
            <p style={{ color: "red", textAlign: "center" }}>{err}</p>
          ) : (
            <>
              <div className="collection-header">
                <span className="collection-count">
                  전체 {collections.length}개
                </span>
                <button
                  className="collection-clear-btn"
                  onClick={handleClearAll}
                >
                  {isTrans ? "전체삭제" : "전체해제"}
                </button>
              </div>

              <div className="collection-list">
                {collections.map((recipe) => (
                  <CollectionItem
                    key={recipe.rcpId}
                    recipe={{
                      id: recipe.rcpId,
                      name: recipe.rcpNm,
                      image: recipe.mainImg,
                      time: recipe.time,
                      servings: recipe.portion,
                      level: recipe.level,
                      liked: recipe.liked,
                    }}
                    isTrans={isTrans}
                    onRemove={() => handleDeleteTrans(recipe.rcpId)}
                    onToggleLike={
                      !isTrans
                        ? () => handleToggleLike(recipe.rcpId)
                        : undefined
                    }
                  />
                ))}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
